from AlgorithmImports import *
from collections import deque
import math


class IndependentSpyAaplStrategies(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_closes = deque(maxlen=100)
        self.spy_previous_close = None
        self.spy_previous_sma = None

        self.aapl_red_streak = 0
        self.aapl_samples = 0
        self.aapl_rsi = self.RSI(
            self.symbols["AAPL"], 14, MovingAverageType.Wilders, Resolution.Daily
        )

        self.spy_lot = 0
        self.aapl_lot = 0

        # This supplies enough pre-start daily observations for the 100-day SMA
        # and a prior fully formed SMA value needed to identify a cross.
        self.SetWarmUp(101, Resolution.Daily)

    def OnData(self, data):
        spy_bar = data.Bars[self.symbols["SPY"]] if data.Bars.ContainsKey(self.symbols["SPY"]) else None
        aapl_bar = data.Bars[self.symbols["AAPL"]] if data.Bars.ContainsKey(self.symbols["AAPL"]) else None

        spy_crosses_above = False
        spy_crosses_below = False

        if spy_bar is not None:
            self.spy_closes.append(float(spy_bar.Close))
            if len(self.spy_closes) == 100:
                spy_sma = sum(self.spy_closes) / 100.0
                if self.spy_previous_sma is not None:
                    spy_crosses_above = (
                        self.spy_previous_close <= self.spy_previous_sma
                        and float(spy_bar.Close) > spy_sma
                    )
                    spy_crosses_below = (
                        self.spy_previous_close >= self.spy_previous_sma
                        and float(spy_bar.Close) < spy_sma
                    )
                self.spy_previous_close = float(spy_bar.Close)
                self.spy_previous_sma = spy_sma

        if aapl_bar is not None:
            self.aapl_samples += 1
            if aapl_bar.Close < aapl_bar.Open:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        required = [self.symbols[ticker] for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]]
        if any(not data.Bars.ContainsKey(symbol) for symbol in required):
            return

        if self.IsWarmingUp:
            return

        indicators_ready = (
            self.spy_previous_sma is not None
            and len(self.spy_closes) == 100
            and self.aapl_samples >= 3
            and self.aapl_rsi.IsReady
        )
        if not indicators_ready:
            return

        # Strategy A: sells are evaluated before buys.
        if self.spy_lot > 0:
            if spy_crosses_below:
                self.MarketOrder(self.symbols["SPY"], -self.spy_lot)
                self.spy_lot = 0
        elif spy_crosses_above:
            close = float(spy_bar.Close)
            quantity = math.floor(0.40 * float(self.Portfolio.TotalPortfolioValue) / close)
            if quantity > 0:
                self.MarketOrder(self.symbols["SPY"], quantity)
                self.spy_lot = quantity

        # Strategy B: sells are evaluated before buys.
        if self.aapl_lot > 0:
            if float(self.aapl_rsi.Current.Value) > 60.0:
                self.MarketOrder(self.symbols["AAPL"], -self.aapl_lot)
                self.aapl_lot = 0
        elif self.aapl_red_streak >= 3 and float(self.Portfolio.Cash) >= 20_000.0:
            quantity = math.floor(20_000.0 / float(aapl_bar.Close))
            if quantity > 0:
                self.MarketOrder(self.symbols["AAPL"], quantity)
                self.aapl_lot = quantity

