class IndependentSpyAaplStrategies(QCAlgorithm):
    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.add_equity(ticker, Resolution.DAILY).symbol

        self.spy_closes = deque(maxlen=101)
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.WILDERS)

        self.strategy_a_lot_open = False
        self.strategy_b_lot_open = False

        self.set_warm_up(101, Resolution.DAILY)

    def on_data(self, data: Slice):
        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]

        if data.bars.contains_key(spy):
            self.spy_closes.appendleft(float(data.bars[spy].close))

        if data.bars.contains_key(aapl):
            aapl_bar = data.bars[aapl]
            if aapl_bar.close < aapl_bar.open:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0
            self.aapl_rsi.update(aapl_bar.end_time, aapl_bar.close)

        if self.is_warming_up:
            return

        if any(not data.bars.contains_key(symbol) for symbol in self.symbols.values()):
            return

        spy_crosses_below = False
        spy_crosses_above = False
        if len(self.spy_closes) == 101:
            today_close = self.spy_closes[0]
            yesterday_close = self.spy_closes[1]
            today_sma = sum(list(self.spy_closes)[:100]) / 100
            yesterday_sma = sum(list(self.spy_closes)[1:101]) / 100
            spy_crosses_above = yesterday_close <= yesterday_sma and today_close > today_sma
            spy_crosses_below = yesterday_close >= yesterday_sma and today_close < today_sma

        # All sell rules are evaluated before any buy rule.
        if self.strategy_a_lot_open and spy_crosses_below:
            self.liquidate(spy)
            self.strategy_a_lot_open = False

        if (
            self.strategy_b_lot_open
            and self.aapl_rsi.is_ready
            and self.aapl_rsi.current.value > 60
        ):
            self.liquidate(aapl)
            self.strategy_b_lot_open = False

        if not self.strategy_a_lot_open and spy_crosses_above:
            quantity = self.calculate_order_quantity(spy, 0.40)
            if quantity > 0:
                self.market_order(spy, quantity)
                self.strategy_a_lot_open = True

        if not self.strategy_b_lot_open and self.aapl_red_streak >= 3:
            if self.portfolio.cash >= 20_000:
                quantity = floor(20_000 / float(data.bars[aapl].close))
                if quantity > 0:
                    self.market_order(aapl, quantity)
                    self.strategy_b_lot_open = True

