class IndependentSpyAaplStrategies(QCAlgorithm):
    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.add_equity(
                ticker, Resolution.DAILY
            ).symbol

        self.spy_closes = deque(maxlen=100)
        self.previous_spy_close = None
        self.previous_spy_sma = None

        self.aapl_rsi = RelativeStrengthIndex(14)
        self.aapl_red_streak = 0

        # These quantities are the private lots belonging to the two strategies.
        self.spy_lot = 0
        self.aapl_lot = 0

    def on_data(self, data: Slice):
        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]

        # Market-state quantities continue to advance whenever their data exists,
        # even on a date on which trading rules must be skipped.
        spy_bar = data.bars[spy] if data.bars.contains_key(spy) else None
        aapl_bar = data.bars[aapl] if data.bars.contains_key(aapl) else None

        spy_crossed_above = False
        spy_crossed_below = False
        if spy_bar is not None:
            self.spy_closes.append(float(spy_bar.close))
            if len(self.spy_closes) == 100:
                current_sma = sum(self.spy_closes) / 100.0
                if self.previous_spy_sma is not None:
                    spy_crossed_above = (
                        self.previous_spy_close <= self.previous_spy_sma
                        and spy_bar.close > current_sma
                    )
                    spy_crossed_below = (
                        self.previous_spy_close >= self.previous_spy_sma
                        and spy_bar.close < current_sma
                    )
                self.previous_spy_sma = current_sma
                self.previous_spy_close = float(spy_bar.close)

        if aapl_bar is not None:
            self.aapl_rsi.update(aapl_bar.end_time, aapl_bar.close)
            if aapl_bar.close < aapl_bar.open:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        # Every subscribed equity must have today's bar before any rule is run.
        if any(not data.bars.contains_key(symbol) for symbol in self.symbols.values()):
            return

        if len(self.spy_closes) < 100 or not self.aapl_rsi.is_ready:
            return

        # Sells are evaluated before buys.
        if self.spy_lot > 0 and spy_crossed_below:
            self.market_order(spy, -self.spy_lot)
            self.spy_lot = 0

        if (
            self.aapl_lot > 0
            and self.aapl_rsi.is_ready
            and self.aapl_rsi.current.value > 60
        ):
            self.market_order(aapl, -self.aapl_lot)
            self.aapl_lot = 0

        if self.spy_lot == 0 and spy_crossed_above:
            quantity = self.calculate_order_quantity(spy, 0.40)
            if quantity > 0:
                self.market_order(spy, quantity)
                self.spy_lot = quantity

        if (
            self.aapl_lot == 0
            and self.aapl_rsi.is_ready
            and self.aapl_red_streak >= 3
            and self.portfolio.cash >= 20_000
        ):
            quantity = floor(20_000 / float(aapl_bar.close))
            if quantity > 0:
                self.market_order(aapl, quantity)
                self.aapl_lot = quantity

    def on_splits(self, splits: Splits):
        # LEAN adjusts security holdings for splits; keep the strategy's private
        # lot ledger in the same units.
        for symbol, split in splits.items():
            if split.type != SplitType.SPLIT_OCCURRED or split.split_factor == 0:
                continue
            if symbol == self.symbols["SPY"] and self.spy_lot:
                self.spy_lot = int(round(self.spy_lot / split.split_factor))
            elif symbol == self.symbols["AAPL"] and self.aapl_lot:
                self.aapl_lot = int(round(self.aapl_lot / split.split_factor))

