        aapl_bar = data.Bars[aapl] if data.Bars.ContainsKey(aapl) else None

        spy_crosses_above = False
        spy_crosses_below = False

        # Market-state quantities advance whenever their ticker has a bar, even
        # when another ticker is missing and trading rules must be skipped.
