            self.spy_closes.append(float(bars["SPY"].Close))

        if "AAPL" in bars:
            aapl_bar = bars["AAPL"]
            if aapl_bar.Close < aapl_bar.Open:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0
            self._update_rsi(float(aapl_bar.Close))

        if len(bars) != len(self.symbols) or self.IsWarmingUp:
            return
        if len(self.spy_closes) < 101 or self.rsi_value is None:
            return

        spy_close = float(bars["SPY"].Close)
        spy_values = list(self.spy_closes)
        spy_sma_today = sum(spy_values[-100:]) / 100.0
        spy_sma_yesterday = sum(spy_values[-101:-1]) / 100.0
        spy_close_yesterday = spy_values[-2]

        # Sells are evaluated before buys.
        if self.strategy_a_shares > 0:
            if (spy_close_yesterday >= spy_sma_yesterday
                    and spy_close < spy_sma_today):
                self.MarketOrder(self.symbols["SPY"], -self.strategy_a_shares)
                self.strategy_a_shares = 0

        if self.strategy_b_shares > 0 and self.rsi_value > 60:
            self.MarketOrder(self.symbols["AAPL"], -self.strategy_b_shares)
            self.strategy_b_shares = 0

        if self.strategy_a_shares == 0:
            if (spy_close_yesterday <= spy_sma_yesterday
                    and spy_close > spy_sma_today):
                quantity = self.CalculateOrderQuantity(self.symbols["SPY"], 0.40)
                if quantity > 0:
                    self.MarketOrder(self.symbols["SPY"], quantity)
                    self.strategy_a_shares = quantity

        if self.strategy_b_shares == 0 and self.aapl_red_streak >= 3:
            if self.Portfolio.Cash >= 20_000:
                quantity = floor(20_000 / float(bars["AAPL"].Close))
                if quantity > 0:
                    self.MarketOrder(self.symbols["AAPL"], quantity)
                    self.strategy_b_shares = quantity

    def _update_rsi(self, close):
        if self.rsi_previous_close is None:
            self.rsi_previous_close = close
            return

        change = close - self.rsi_previous_close
        gain = max(change, 0.0)
        loss = max(-change, 0.0)
        self.rsi_previous_close = close

        if self.rsi_average_gain is None:
            self.rsi_gains.append(gain)
            self.rsi_losses.append(loss)
            if len(self.rsi_gains) < 14:
                return
            self.rsi_average_gain = sum(self.rsi_gains) / 14.0
            self.rsi_average_loss = sum(self.rsi_losses) / 14.0
        else:
            self.rsi_average_gain = (13.0 * self.rsi_average_gain + gain) / 14.0
            self.rsi_average_loss = (13.0 * self.rsi_average_loss + loss) / 14.0

        if self.rsi_average_loss == 0:
            self.rsi_value = 100.0 if self.rsi_average_gain > 0 else 0.0
        else:
            relative_strength = self.rsi_average_gain / self.rsi_average_loss
            self.rsi_value = 100.0 - 100.0 / (1.0 + relative_strength)

