class IndependentSpyAndAppleStrategies(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol
        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_sma = SimpleMovingAverage(100)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.aapl_red_streak = 0
        self.aapl_bar_count = 0

        self.spy_lot = 0
        self.aapl_lot = 0
        self.spy_order_pending = False
        self.aapl_order_pending = False

    def OnData(self, data: Slice):
        if data.Bars.ContainsKey(self.spy):
            spy_bar = data.Bars[self.spy]
            old_close = self.previous_spy_close
            old_sma = self.previous_spy_sma
            self.spy_sma.Update(spy_bar.EndTime, spy_bar.Close)
            current_sma = self.spy_sma.Current.Value if self.spy_sma.IsReady else None
            self.previous_spy_close = spy_bar.Close
            self.previous_spy_sma = current_sma
        else:
            spy_bar = None
            old_close = None
            old_sma = None
            current_sma = None

        if data.Bars.ContainsKey(self.aapl):
            aapl_bar = data.Bars[self.aapl]
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)
            self.aapl_bar_count += 1
            if aapl_bar.Close < aapl_bar.Open:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0
        else:
            aapl_bar = None

        # A lot is private to its strategy; these tickers have no other owners.
        # Synchronizing from holdings also incorporates split adjustments.
        if not self.spy_order_pending:
            self.spy_lot = int(self.Portfolio[self.spy].Quantity)
        if not self.aapl_order_pending:
            self.aapl_lot = int(self.Portfolio[self.aapl].Quantity)

        if any(not data.Bars.ContainsKey(symbol) for symbol in self.symbols):
            return

        all_state_ready = (
            self.spy_sma.IsReady
            and self.aapl_rsi.IsReady
            and old_close is not None
            and old_sma is not None
            and self.aapl_bar_count >= 3
        )
        if not all_state_ready:
            return

        # Sells are evaluated before buys.  Each strategy can evaluate only the
        # side appropriate to the state of its own lot.
        if self.spy_lot > 0 and not self.spy_order_pending:
            crossed_below = old_close >= old_sma and spy_bar.Close < current_sma
            if crossed_below:
                self.spy_order_pending = True
                self.MarketOrder(self.spy, -self.spy_lot, tag="Strategy A sell")

        if self.aapl_lot > 0 and not self.aapl_order_pending:
            if self.aapl_rsi.Current.Value > 60:
                self.aapl_order_pending = True
                self.MarketOrder(self.aapl, -self.aapl_lot, tag="Strategy B sell")

        if self.spy_lot == 0 and not self.spy_order_pending:
            crossed_above = old_close <= old_sma and spy_bar.Close > current_sma
            if crossed_above:
                quantity = self.CalculateOrderQuantity(self.spy, 0.40)
                if quantity > 0:
                    self.spy_order_pending = True
                    self.MarketOrder(self.spy, quantity, tag="Strategy A buy")

        if self.aapl_lot == 0 and not self.aapl_order_pending:
            if self.aapl_red_streak >= 3 and self.Portfolio.Cash >= 20_000:
                quantity = int(20_000 // aapl_bar.Close)
                if quantity > 0:
                    self.aapl_order_pending = True
                    self.MarketOrder(self.aapl, quantity, tag="Strategy B buy")

    def OnOrderEvent(self, order_event: OrderEvent):
        order = self.Transactions.GetOrderById(order_event.OrderId)
        if order is None:
            return

        if order.Symbol == self.spy:
            self.spy_lot += int(order_event.FillQuantity)
            if order_event.Status in [OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid]:
                self.spy_order_pending = False
        elif order.Symbol == self.aapl:
            self.aapl_lot += int(order_event.FillQuantity)
            if order_event.Status in [OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid]:
                self.aapl_order_pending = False

