class IndependentSlotsAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_sma = SimpleMovingAverage(100)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.spy_previous_above_sma = None
        self.aapl_red_streak = 0

        self.spy_lot = 0
        self.aapl_lot = 0

        # This supplies enough observations for both today's and yesterday's
        # fully formed 100-day SMA relationship before live rule evaluation.
        self.SetWarmUp(101, Resolution.Daily)

    def OnData(self, data: Slice):
        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]

        spy_crossed_above = False
        spy_crossed_below = False

        if spy in data.Bars:
            spy_bar = data.Bars[spy]
            self.spy_sma.Update(spy_bar.EndTime, spy_bar.Close)
            if self.spy_sma.IsReady:
                spy_above_sma = spy_bar.Close > self.spy_sma.Current.Value
                if self.spy_previous_above_sma is not None:
                    spy_crossed_above = (
                        not self.spy_previous_above_sma and spy_above_sma
                    )
                    spy_crossed_below = (
                        self.spy_previous_above_sma and not spy_above_sma
                    )
                self.spy_previous_above_sma = spy_above_sma

        if aapl in data.Bars:
            aapl_bar = data.Bars[aapl]
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)
            if aapl_bar.Close < aapl_bar.Open:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        all_bars_present = all(
            symbol in data.Bars for symbol in self.symbols.values()
        )
        if self.IsWarmingUp or not all_bars_present:
            return

        # Evaluate every sell before any buy.
        if self.spy_lot > 0 and spy_crossed_below:
            self.MarketOrder(spy, -self.spy_lot)
            self.spy_lot = 0

        if (
            self.aapl_lot > 0
            and self.aapl_rsi.IsReady
            and self.aapl_rsi.Current.Value > 60
        ):
            self.MarketOrder(aapl, -self.aapl_lot)
            self.aapl_lot = 0

        if self.spy_lot == 0 and spy_crossed_above:
            quantity = int(
                0.40 * self.Portfolio.TotalPortfolioValue / data.Bars[spy].Close
            )
            if quantity > 0:
                self.MarketOrder(spy, quantity)
                self.spy_lot = quantity

        if self.aapl_lot == 0 and self.aapl_red_streak >= 3:
            cash_to_invest = 20_000
            if self.Portfolio.Cash >= cash_to_invest:
                quantity = int(cash_to_invest // data.Bars[aapl].Close)
                if quantity > 0:
                    self.MarketOrder(aapl, quantity)
                    self.aapl_lot = quantity

