class IndependentSpyAaplStrategies(QCAlgorithm):
    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.add_equity(
                ticker, Resolution.DAILY
            ).symbol

        self.spy_sma = SimpleMovingAverage(100)
        self.aapl_rsi = RelativeStrengthIndex(
            14, MovingAverageType.WILDERS
        )

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.aapl_red_streak = 0

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

        # The extra bar makes both sides of the first possible SMA crossover
        # fully formed before live rule evaluation begins.
        self.set_warm_up(101, Resolution.DAILY)

    def on_data(self, data: Slice):
        spy_bar = data.bars.get(self.symbols["SPY"])
        aapl_bar = data.bars.get(self.symbols["AAPL"])

        # Market-state quantities continue to advance whenever their own data
        # is present, even when another subscription is missing for the day.
        previous_spy_close = self.previous_spy_close
        previous_spy_sma = self.previous_spy_sma

        if spy_bar is not None:
            self.spy_sma.update(spy_bar.end_time, spy_bar.close)

        if aapl_bar is not None:
            self.aapl_rsi.update(aapl_bar.end_time, aapl_bar.close)
            if aapl_bar.close < aapl_bar.open:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        all_bars_present = all(
            data.bars.get(symbol) is not None
            for symbol in self.symbols.values()
        )

        if (
            not self.is_warming_up
            and all_bars_present
            and self.spy_sma.is_ready
            and self.aapl_rsi.is_ready
        ):
            # Sells are evaluated before buys on every eligible bar.
            if self.strategy_a_shares > 0:
                crosses_below = (
                    previous_spy_close is not None
                    and previous_spy_sma is not None
                    and previous_spy_close >= previous_spy_sma
                    and spy_bar.close < self.spy_sma.current.value
                )
                if crosses_below:
                    self.market_order(
                        self.symbols["SPY"], -self.strategy_a_shares
                    )
                    self.strategy_a_shares = 0

            if (
                self.strategy_b_shares > 0
                and self.aapl_rsi.current.value > 60
            ):
                self.market_order(
                    self.symbols["AAPL"], -self.strategy_b_shares
                )
                self.strategy_b_shares = 0

            if self.strategy_a_shares == 0:
                crosses_above = (
                    previous_spy_close is not None
                    and previous_spy_sma is not None
                    and previous_spy_close <= previous_spy_sma
                    and spy_bar.close > self.spy_sma.current.value
                )
                if crosses_above:
                    shares = int(
                        (self.portfolio.total_portfolio_value * 0.40)
                        // spy_bar.close
                    )
                    if shares > 0:
                        self.market_order(self.symbols["SPY"], shares)
                        self.strategy_a_shares = shares

            if (
                self.strategy_b_shares == 0
                and self.aapl_red_streak >= 3
                and self.portfolio.cash >= 20_000
            ):
                shares = int(20_000 // aapl_bar.close)
                if shares > 0:
                    self.market_order(self.symbols["AAPL"], shares)
                    self.strategy_b_shares = shares

        if spy_bar is not None:
            self.previous_spy_close = spy_bar.close
            if self.spy_sma.is_ready:
                self.previous_spy_sma = self.spy_sma.current.value

from AlgorithmImports import *
from collections import deque
import math


class ParallelSpyAaplStrategies(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_closes = deque(maxlen=101)
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.spy_lot = 0
        self.aapl_lot = 0

    def OnData(self, data):
        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]

        if data.Bars.ContainsKey(spy):
            self.spy_closes.append(float(data.Bars[spy].Close))

        if data.Bars.ContainsKey(aapl):
            aapl_bar = data.Bars[aapl]
            if aapl_bar.Close < aapl_bar.Open:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)

        if any(not data.Bars.ContainsKey(symbol) for symbol in self.symbols.values()):
            return

        spy_bar = data.Bars[spy]
        aapl_bar = data.Bars[aapl]

        spy_ready = len(self.spy_closes) == 101
        if spy_ready:
            closes = list(self.spy_closes)
            yesterday_close = closes[-2]
            today_close = closes[-1]
            yesterday_sma = sum(closes[-101:-1]) / 100.0
            today_sma = sum(closes[-100:]) / 100.0
            spy_crossed_above = yesterday_close <= yesterday_sma and today_close > today_sma
            spy_crossed_below = yesterday_close >= yesterday_sma and today_close < today_sma
        else:
            spy_crossed_above = False
            spy_crossed_below = False

        # Evaluate every sell before evaluating either strategy's buy.
        if self.spy_lot > 0 and spy_crossed_below:
            self.MarketOrder(spy, -self.spy_lot)
            self.spy_lot = 0

        if self.aapl_lot > 0 and self.aapl_rsi.IsReady and self.aapl_rsi.Current.Value > 60:
            self.MarketOrder(aapl, -self.aapl_lot)
            self.aapl_lot = 0

        if self.spy_lot == 0 and spy_crossed_above:
            quantity = math.floor(0.40 * float(self.Portfolio.TotalPortfolioValue) / float(spy_bar.Close))
            if quantity > 0:
                self.MarketOrder(spy, quantity)
                self.spy_lot = quantity

        if self.aapl_lot == 0 and self.aapl_red_streak >= 3:
            cash_to_invest = 20_000.0
            if float(self.Portfolio.Cash) >= cash_to_invest:
                quantity = math.floor(cash_to_invest / float(aapl_bar.Close))
                if quantity > 0:
                    self.MarketOrder(aapl, quantity)
                    self.aapl_lot = quantity

