class ParallelSpyAaplStrategies(QCAlgorithm):
    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.add_equity(
                ticker, Resolution.DAILY
            ).symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.spy_closes = deque(maxlen=100)
        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.aapl_red_streak = 0
        self.aapl_rsi = self.rsi(
            self.aapl, 14, MovingAverageType.WILDERS, Resolution.DAILY
        )

        # Each quantity is the private lot owned by its respective strategy.
        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def on_data(self, data: Slice):
        spy_bar = data.bars[self.spy] if data.bars.contains_key(self.spy) else None
        aapl_bar = (
            data.bars[self.aapl] if data.bars.contains_key(self.aapl) else None
        )

        spy_crosses_above = False
        spy_crosses_below = False
        current_spy_sma = None

        if spy_bar is not None:
            self.spy_closes.append(float(spy_bar.close))
            if len(self.spy_closes) == 100:
                current_spy_sma = sum(self.spy_closes) / 100.0
                if self.previous_spy_sma is not None:
                    spy_crosses_above = (
                        self.previous_spy_close <= self.previous_spy_sma
                        and float(spy_bar.close) > current_spy_sma
                    )
                    spy_crosses_below = (
                        self.previous_spy_close >= self.previous_spy_sma
                        and float(spy_bar.close) < current_spy_sma
                    )

        if aapl_bar is not None:
            if aapl_bar.close < aapl_bar.open:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        all_bars_present = all(
            data.bars.contains_key(symbol) for symbol in self.symbols.values()
        )

        if all_bars_present:
            # Sells are evaluated before buys across both independent slots.
            if self.strategy_a_shares > 0 and spy_crosses_below:
                self.market_order(self.spy, -self.strategy_a_shares)
                self.strategy_a_shares = 0

            if (
                self.strategy_b_shares > 0
                and self.aapl_rsi.is_ready
                and self.aapl_rsi.current.value > 60
            ):
                self.market_order(self.aapl, -self.strategy_b_shares)
                self.strategy_b_shares = 0

            if self.strategy_a_shares == 0 and spy_crosses_above:
                quantity = self.calculate_order_quantity(self.spy, 0.40)
                if quantity > 0:
                    self.market_order(self.spy, quantity)
                    self.strategy_a_shares = quantity

            if self.strategy_b_shares == 0 and self.aapl_red_streak >= 3:
                cash_amount = 20_000
                if self.portfolio.cash >= cash_amount:
                    quantity = floor(cash_amount / float(aapl_bar.close))
                    if quantity > 0:
                        self.market_order(self.aapl, quantity)
                        self.strategy_b_shares = quantity

        # Cross state advances whenever SPY has a bar, even on a day whose rules
        # were skipped because another subscription was missing.
        if current_spy_sma is not None:
            self.previous_spy_close = float(spy_bar.close)
            self.previous_spy_sma = current_spy_sma

from AlgorithmImports import *
from collections import deque
from math import floor


class IndependentSpyAaplStrategies(QCAlgorithm):
    """Two independent, close-of-day strategies with separately tracked lots."""

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol
        self.symbols = (self.spy, self.aapl, self.ibm, self.bac, self.aig)

        # 101 closes provide fully formed 100-day SMAs for both today and yesterday.
        self.spy_closes = deque(maxlen=101)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)
        self.aapl_red_streak = 0

        # Each strategy owns only the shares recorded in its private lot.
        self.spy_lot = 0
        self.aapl_lot = 0
        self.pending_orders = {}

    def OnData(self, data: Slice):
        # Market-state quantities continue to update even when another ticker is absent.
        if data.Bars.ContainsKey(self.spy):
            self.spy_closes.append(float(data.Bars[self.spy].Close))

        if data.Bars.ContainsKey(self.aapl):
            bar = data.Bars[self.aapl]
            self.aapl_rsi.Update(bar.EndTime, bar.Close)
            if bar.Close < bar.Open:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        # A missing daily bar for any subscription suppresses every rule for the day.
        if any(not data.Bars.ContainsKey(symbol) for symbol in self.symbols):
            return

        if len(self.spy_closes) < 101 or not self.aapl_rsi.IsReady:
            return

        spy_close = self.spy_closes[-1]
        spy_previous_close = self.spy_closes[-2]
        spy_sma_today = sum(list(self.spy_closes)[-100:]) / 100.0
        spy_sma_yesterday = sum(list(self.spy_closes)[:-1]) / 100.0

        # Sells are evaluated before buys. The two lots otherwise run independently.
        if self.spy_lot > 0:
            crossed_below = (
                spy_previous_close >= spy_sma_yesterday
                and spy_close < spy_sma_today
            )
            if crossed_below:
                self._submit_lot_order(self.spy, -self.spy_lot, "spy")
        else:
            crossed_above = (
                spy_previous_close <= spy_sma_yesterday
                and spy_close > spy_sma_today
            )
            if crossed_above:
                quantity = self.CalculateOrderQuantity(self.spy, 0.40)
                if quantity > 0:
                    self._submit_lot_order(self.spy, quantity, "spy")

        if self.aapl_lot > 0:
            if self.aapl_rsi.Current.Value > 60:
                self._submit_lot_order(self.aapl, -self.aapl_lot, "aapl")
        elif self.aapl_red_streak >= 3 and self.Portfolio.Cash >= 20_000:
            quantity = floor(20_000 / float(data.Bars[self.aapl].Close))
            if quantity > 0:
                self._submit_lot_order(self.aapl, quantity, "aapl")

    def _submit_lot_order(self, symbol, quantity, lot_name):
        ticket = self.MarketOrder(symbol, quantity)
        self.pending_orders[ticket.OrderId] = lot_name

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status not in (OrderStatus.PartiallyFilled, OrderStatus.Filled):
            return

        lot_name = self.pending_orders.get(order_event.OrderId)
        if lot_name == "spy":
            self.spy_lot += int(order_event.FillQuantity)
        elif lot_name == "aapl":
            self.aapl_lot += int(order_event.FillQuantity)

        if order_event.Status == OrderStatus.Filled:
            self.pending_orders.pop(order_event.OrderId, None)

